obj BoardController {
    has scene: any = None, camera: any = None, renderer: any = None,
        labeler: any = None, controls: any = None, clock: any = None;
    has world_group: any = None, city_group: any = None;
    has landmarks: dict = {}, city_pos: dict = {};
    has travel: any = None, cam_anim: any = None, glow_rings: list = [];
    has level: str = "world", on_city_click: any = None;
    has _label_recs: list = [];

    def init(container: any = None) -> None {
        if not container { return; }
        w = container.clientWidth;
        h = container.clientHeight;
        self.scene = new(Scene);
        self.scene.background = new(Color, 0x1a1a2e);
        self.scene.fog = new(Fog, 0x1a1a2e, 50, 150);
        self.camera = new(PerspectiveCamera, 50, w / h, 0.5, 300);
        self.camera.position.set(16, 20, 24);
        self.renderer = new(WebGLRenderer, {"antialias": True});
        self.renderer.setSize(w, h);
        self.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        self.renderer.shadowMap.enabled = True;
        self.renderer.shadowMap.type = PCFSoftShadowMap;
        self.renderer.toneMapping = ACESFilmicToneMapping;
        self.renderer.toneMappingExposure = 1.1;
        container.appendChild(self.renderer.domElement);

        self.labeler = new(CSS2DRenderer);
        self.labeler.setSize(w, h);
        self.labeler.domElement.style.position = "absolute";
        self.labeler.domElement.style.top = "0px";
        self.labeler.domElement.style.pointerEvents = "none";
        container.appendChild(self.labeler.domElement);

        self.controls = new(OrbitControls, self.camera, self.renderer.domElement);
        self.controls.target.set(0, 0, 0);
        self.controls.enableDamping = True;
        self.controls.maxPolarAngle = Math.PI / 2.1;
        self.controls.minDistance = 3;
        self.controls.maxDistance = 60;

        self.scene.add(new(AmbientLight, 0x334466, 1.8));
        sun: any = new(DirectionalLight, 0xffeedd, 5);
        sun.position.set(30, 35, 15);
        sun.castShadow = True;
        self.scene.add(sun);

        self.clock = new(Clock);
        tick = lambda -> None {
            requestAnimationFrame(tick);
            self._frame();
        };
        tick();
    }

    def _frame -> None {
        dt = Math.min(self.clock.getDelta(), 0.1);
        self.controls.update();
        self._update_camera();
        self._update_travel(dt);
        win: any = window;
        t = float(win.performance.now()) * 0.001;
        for r in self.glow_rings {
            s = 1 + Math.sin(t * 3) * 0.15;
            r.scale.set(s, s, s);
        }
