    def _set_group_labels_visible(group: any, visible: bool) -> None {
        for rec in self._label_recs {
            if self._is_descendant(group, rec["obj"]) {
                rec["obj"].visible = visible;
            }
        }
    }

    def _is_descendant(group: any, target: any) -> bool {
        p = target.parent;
        while p {
            if p is group { return True; }
            p = p.parent;
        }
        return False;
    }

    def build_world(cities: list) -> None {
        g: any = new(Group);
        ocean: any = new(Mesh, 
            new(PlaneGeometry, 70, 50),
            new(MeshStandardMaterial, {"color": 0x162544, "roughness": 0.55, "metalness": 0.35})
        );
        ocean.rotation.x = -Math.PI / 2;
        ocean.position.y = -0.3;
        ocean.receiveShadow = True;
        g.add(ocean);

        board: any = new(Mesh, 
            new(CylinderGeometry, 18, 18.5, 0.3, 64),
            new(MeshStandardMaterial, {"color": 0x2a2840, "roughness": 0.4, "metalness": 0.2})
        );
        board.position.y = -0.45;
        board.receiveShadow = True;
        g.add(board);

        rim: any = new(Mesh, 
            new(TorusGeometry, 18.25, 0.2, 16, 96),
            new(MeshStandardMaterial, {"color": 0xc9a96e, "roughness": 0.3, "metalness": 0.7, "emissive": 0x332200, "emissiveIntensity": 0.3})
        );
        rim.rotation.x = -Math.PI / 2;
        rim.position.y = -0.29;
        g.add(rim);

        grid: any = new(PolarGridHelper, 28, 40, 36, 80, 0x334466, 0x223355);
        grid.position.y = -0.28;
        g.add(grid);

        for c in cities {
            cname = str(c.name);
            cms: any = c.match_score;
            self.city_pos[c.name] = {"x": c.board_x, "z": c.board_z};
            color = _city_color(cname);
            mat: any = new(MeshStandardMaterial, {"color": color, "roughness": 0.25, "metalness": 0.4});
            piece: any = new(Group);
            if c.home {
                body: any = new(Mesh, new(CylinderGeometry, 0.22, 0.32, 1, 8), mat);
                body.position.y = 0.45;
                piece.add(body);
                orb: any = new(Mesh, 
                    new(SphereGeometry, 0.22, 16, 12),
                    new(MeshStandardMaterial, {"color": 0xffaa44, "emissive": 0xff6600, "emissiveIntensity": 0.7})
                );
                orb.position.y = 0.9;
                piece.add(orb);
                self._label("🏠 " + cname, "color:#ffcc66;font-size:15px;font-weight:700", 0, 1.9, 0, piece);
            } else {
                tower: any = new(Mesh, new(CylinderGeometry, 0.18, 0.3, 1.8, 8), mat);
                tower.position.y = 0.4;
                tower.castShadow = True;
                piece.add(tower);
                spire: any = new(Mesh, new(ConeGeometry, 0.1, 0.6, 8), mat);
                spire.position.y = 1.3;
                piece.add(spire);
                base: any = new(Mesh, 
                    new(CylinderGeometry, 0.35, 0.4, 0.12, 16),
                    new(MeshStandardMaterial, {"color": 0x444466})
                );
                base.position.y = -0.05;
                piece.add(base);
                self._label(cname, "color:#ddd;font-size:11px;font-weight:500", 0, 1.6, 0, piece);
                if cms {
                    self._label(
                        _stars(int(cms)) + " " + str(cms) + "%",
                        "color:#f0c040;font-size:13px", 0, 1.95, 0, piece
                    );
                }
                piece.userData = {"city": c.name};
            }
            piece.position.set(c.board_x, -0.1, c.board_z);
            g.add(piece);
            self.landmarks[c.name] = piece;
        }

        # route curves from Shanghai
        if "Shanghai" in self.city_pos {
            sh: any = self.city_pos["Shanghai"];
            shx = float(sh["x"]);
            shz = float(sh["z"]);
            for c in cities {
                if c.home { continue; }
                p: any = self.city_pos[c.name];
                px = float(p["x"]);
                pz = float(p["z"]);
                curve: any = new(QuadraticBezierCurve3, 
                    new(Vector3, shx, 0.05, shz),
                    new(Vector3, (shx + px) / 2, 0.8, (shz + pz) / 2),
                    new(Vector3, px, 0.05, pz)
                );
                bgeo: any = new(BufferGeometry);
                line: any = new(Line,
                    bgeo.setFromPoints(curve.getPoints(60)),
                    new(LineBasicMaterial, {"color": 0x4466aa, "transparent": True, "opacity": 0.35})
                );
                g.add(line);
                self._label("✈️", "font-size:16px", (shx + px) / 2, 1.1, (shz + pz) / 2, g);
            }
        }

        # stars skybox
        sp = [];
        i = 0;
        while i < 800 {
            sp.append((Math.random() - 0.5) * 55);
            sp.append(5 + Math.random() * 18);
            sp.append((Math.random() - 0.5) * 40);
            i = i + 1;
        }
        geo: any = new(BufferGeometry);
        geo.setAttribute("position", new(BufferAttribute, new(Float32Array, sp), 3));
        g.add(new(Points, geo, new(PointsMaterial, {"color": 0xffffff, "size": 0.04, "transparent": True, "opacity": 0.5})));

        self.world_group = g;
        self.scene.add(g);

        # double-click a landmark → pick that city
        ray: any = new(Raycaster);
        mouse: any = new(Vector2);
        def handle_dblclick(e: any) -> None {
            rect: any = self.renderer.domElement.getBoundingClientRect();
            rl = float(rect.left);
            rt = float(rect.top);
            rw = float(rect.width);
            rh = float(rect.height);
            ex = float(e.clientX);
            ey = float(e.clientY);
            mouse.x = ((ex - rl) / rw) * 2 - 1;
            mouse.y = -((ey - rt) / rh) * 2 + 1;
            ray.setFromCamera(mouse, self.camera);
            names = Object.keys(self.landmarks);
            ni = 0;
            nn = len(names);
            while ni < nn {
                hits = ray.intersectObject(self.landmarks[names[ni]], True);
                if hits.length > 0 and self.on_city_click and self.level == "world" {
                    self.on_city_click(names[ni]);
                    return;
                }
                ni = ni + 1;
            }
        }
        self.renderer.domElement.addEventListener("dblclick", handle_dblclick);
    }

    def _fly_camera(px: float, py: float, pz: float, tx: float, ty: float, tz: float) -> None {
        self.cam_anim = {
            "sp": self.camera.position.clone(), "ep": new(Vector3, px, py, pz),
            "st": self.controls.target.clone(), "et": new(Vector3, tx, ty, tz),
            "t": 0.0
        };
    }

    def _update_camera -> None {
        if not self.cam_anim { return; }
        a = self.cam_anim;
        a["t"] = Math.min(a["t"] + 0.016 / 1.4, 1);
        at = float(a["t"]);
        e = at * at * (3 - 2 * at);
        self.camera.position.lerpVectors(a["sp"], a["ep"], e);
        self.controls.target.lerpVectors(a["st"], a["et"], e);
        if a["t"] >= 1 { self.cam_anim = None; }
    }

    def travel_to(city_name: str, mode: str, on_done: any) -> None {
        sh: any = self.city_pos["Shanghai"];
        p: any = self.city_pos[city_name];
        shx = float(sh["x"]);
        shz = float(sh["z"]);
        px = float(p["x"]);
        pz = float(p["z"]);
        vehicle: any = new(Group);
        vbody: any = new(Mesh, 
            new(CapsuleGeometry, 0.12, 0.5, 4, 8),
            new(MeshStandardMaterial, {"color": 0xffffff, "roughness": 0.2})
        );
        vbody.rotation.x = Math.PI / 2;
        vehicle.add(vbody);
        wing: any = new(Mesh, new(BoxGeometry, 0.8, 0.03, 0.18), new(MeshStandardMaterial, {"color": 0xdddddd}));
        vehicle.add(wing);
        vehicle.position.set(shx, 0.3, shz);
        self.scene.add(vehicle);
        curve: any = new(QuadraticBezierCurve3, 
            new(Vector3, shx, 0.3, shz),
            new(Vector3, (shx + px) / 2, 4.5, (shz + pz) / 2),
            new(Vector3, px, 0.05, pz)
        );
        self.travel = {"v": vehicle, "curve": curve, "t": 0.0, "on_done": on_done};
    }

    def _update_travel(dt: float) -> None {
        if not self.travel { return; }
        tr = self.travel;
        tr["t"] = tr["t"] + dt * 0.4;
        if tr["t"] >= 1 {
            self.scene.remove(tr["v"]);
            cb = tr["on_done"];
            self.travel = None;
            if cb { cb(); }
            return;
        }
        pt = tr["curve"].getPoint(tr["t"]);
        tr["v"].position.copy(pt);
    }

    def enter_city(city_name: str, items: list) -> None {
        self.level = "city";
        if self.world_group {
            self.world_group.visible = False;
            self._set_group_labels_visible(self.world_group, False);
        }
        if self.city_group {
            self._set_group_labels_visible(self.city_group, False);
            self.scene.remove(self.city_group);
        }
        self.glow_rings = [];
        g: any = new(Group);

        ground: any = new(Mesh, 
            new(CylinderGeometry, 8, 8.3, 0.5, 64),
            new(MeshStandardMaterial, {"color": 0x3d3a55, "roughness": 0.3, "metalness": 0.4})
        );
        ground.position.y = -0.5;
        g.add(ground);

        crim: any = new(Mesh, 
            new(TorusGeometry, 8.15, 0.2, 8, 80),
            new(MeshStandardMaterial, {"color": 0xc9a96e, "metalness": 0.75, "emissive": 0x332200, "emissiveIntensity": 0.6})
        );
