        f"person={ctx.person_name}\nchannel={ctx.channel}\n"
        f"incoming={ctx.incoming}\nthread={ctx.thread_context}\nopen={acts}\n"
    );
    data = _extract_json_obj(cloud_chat(prompt, 160));
