                    props["className"]
                )}
                {**attrs}
            >
                {props["children"]}
            </div>;
    } elif isMobile {
        mobileStyle = {"--sidebar-width": SIDEBAR_WIDTH_MOBILE};
        return
            <Sheet open={openMobile} onOpenChange={setOpenMobile} {**props}>
                <SheetContent
                    dir={props["dir"]}
                    data-sidebar="sidebar"
                    data-slot="sidebar"
                    data-mobile="true"
                    className="bg-sidebar text-sidebar-foreground w-(--sidebar-width) p-0 [&>button]:hidden"
