# written in jac
# from: jachacks-sf::PMN123__trapdoor::engine__policy.jac
"""Trapdoor engine - domain types.

Every authoritative thing in Trapdoor is a node on the persistent Jac graph:
the pinned regulation, its clauses in precedence order, the applicants we run
through them, the invariants a repair may not break, and the audit trail of
what the agent tried.

The trust boundary lives in these declarations. `Clause` is authoritative and
is never written by an LLM. `PatchCandidate` is the only shape a proposed
change can take, and it is created `STAGED` - never active.
"""

# --------------------------------------------------------------------------
# Enums - the closed vocabularies the UI and the LLM both bind to.
# --------------------------------------------------------------------------

enum Verdict: str {
    ELIGIBLE = "ELIGIBLE",
    DENIED = "DENIED",
    NEEDS_REVIEW = "NEEDS_REVIEW"
}

enum ClauseStatus: str {
    PASS = "PASS",
    FAIL = "FAIL",
    INDETERMINATE = "INDETERMINATE"
}

enum PatchStatus: str {
    STAGED = "STAGED",
    ACCEPTED = "ACCEPTED",
    REJECTED = "REJECTED"
}

# --------------------------------------------------------------------------
# Nodes
# --------------------------------------------------------------------------

node Source {
    """The pinned, blinded regulatory snapshot. Post-T material never lands here."""
    has citation: str;
    has snapshot_date: str;
    has source_url: str;
    has body: str;
    has ingest_mode: str = "HAND_EXTRACT";
    has stripped_elements: list[str] = [];
    has stripped_count: int = 0;
    has provenance_note: str = "";
    has body_sha256: str = "";
}

node Policy {
    """A versioned regulation. `version` is the snapshot date, so the graph can hold more than one."""
    has policy_id: str;
    has title: str;
    has citation: str;
    has version: str;
    has jurisdiction: str = "US-FEDERAL";
}

node Clause {
    """One atomic, source-addressable rule. Authoritative - no LLM ever writes this."""
    has clause_id: str;
    has citation: str;
    has heading: str;
    has precedence: int;
    has test_key: str;
    has text: str;
    has param_days: int = 0;
    has fail_verdict: Verdict = Verdict.DENIED;
}

node Applicant {
    """Synthetic facts about one worker. Never real personal data."""
    has case_id: str;
    has label: str;
    has category: str;
    has renewal_category: str;
    has ead_expires_on: str;
    has renewal_filed_on: str;
    has as_of: str;
    has renewal_pending: bool = True;
    has renewal_denied: bool = False;
    has continuing_eligibility: str = "yes";
    has control_kind: str = "GENERATED";
    has expected_verdict: Verdict = Verdict.NEEDS_REVIEW;
    has notes: str = "";
}

node Invariant {
    """A property a repair may not break. Checked deterministically, never by a model."""
    has invariant_id: str;
    has kind: str;
    has heading: str;
    has statement: str;
}

node Outcome {
    """The result of one deterministic evaluation: verdict, ordered trace, first failure."""
    has outcome_id: str;
    has case_id: str;
    has policy_version: str;
    has verdict: Verdict;
    has trace: list[str] = [];
    has first_failing_clause: str = "";
    has reason: str = "";
    has evaluated_as_of: str = "";
}

node Attempt {
    """One red-team iteration. Persisted so the agent has memory across the demo."""
    has attempt_id: str;
    has goal: str;
    has defect_pattern: str = "";
    has hypothesis: str = "";
    has probe_case_id: str = "";
    has tool_calls: list[str] = [];
    has confirmed: bool = False;
}

node Finding {
    """A minimised counterexample plus the invariant it violates.

    `minimal_facts` is 1-minimal: every fact still in it is load-bearing, and
    `minimality_checks` records what deleting each one does to the violation.

    `first_failing_clause` is the rung the violation actually died on. It is
    the gate on drafting: a proposed repair may only amend the clause the
    counterexample proves is broken, so this field is what the deterministic
    validator checks a model's draft against.
    """
    has finding_id: str;
    has case_id: str;
    has violated_invariant: str;
    has minimal_facts: list[str] = [];
    has summary: str = "";
    has original_facts: list[str] = [];
    has removed_facts: list[str] = [];
    has removal_order: list[str] = [];
    has minimality_checks: list[str] = [];
    has one_minimal: bool = False;
    has evaluations: int = 0;
    has first_failing_clause: str = "";
}

node PatchCandidate {
    """A proposed clause change. Created STAGED. Only the regression walker may accept it.

    `bypasses_predecessors` is the single field separating the two candidates:
    a narrow repair retunes its target rung and leaves every earlier rung
    standing, a broad one waives them. Making that a field rather than a
    special case inside the evaluator is why the regression can *name* what
    escaped instead of just failing.

    `origin` records where the proposal came from and is covered by the freeze
    digest, so a run in which the model stalled can never be presented as a
    model-drafted retrodiction:

      MODEL_DRAFT   the typed byLLM draft, after the deterministic validator
                    accepted it. This is the candidate that gets regressed.
      DERIVED_BROAD the deliberately overbroad negative control, built by Jac
                    from the same draft - same target, same parameter, every
                    earlier condition waived.
      FALLBACK_CACHED  the hand-written candidate used only when drafting
                    stalled or failed validation. Hand-chosen, not derived.

    The three temporal fields describe what the proposal actually does in time.
    They are structural facts about the candidate, not commentary, and the
    answer-key comparison grades them rather than asserting a verdict: a plain
    parameter change is permanent, carries no filing window, and revives
    nobody whose authorization already lapsed.
    """
    has patch_id: str;
    has target_clause_id: str;
    has kind: str;
    has proposed_text: str;
    has proposed_param_days: int = 0;
    has rationale: str = "";
    has status: PatchStatus = PatchStatus.STAGED;
    has rejected_because: str = "";
    has bypasses_predecessors: bool = False;
    has origin: str = "FALLBACK_CACHED";
    has finding_id: str = "";
    has derived_from_patch_id: str = "";
    has is_temporary: bool = False;
    has filing_window: str = "";
    has resumes_lapsed_authorizations: bool = False;
}

node FrozenProposal {
    """An accepted proposal, sealed before the answer key may be opened.

    `sha256` is taken over `canonical_payload`, which since v3 is built from
    **every** field of the finding, **every** field of the target clause and
    **every** field of the patch bar the seal itself - so the hash moves if any
    of them move. The rule is structural rather than a hand-picked list,
    because the hand-picked list left out `Clause.test_key`, which the answer
    key grades on. Freezing is what earns the right to look at what actually
    happened.

    **APPEND-ONLY. Nothing in this repository writes to a FrozenProposal after
    it is created.** A seal that could be rewritten is not a seal: re-freezing
    the identical payload hands back the existing receipt untouched, and
    re-freezing changed data is refused with both digests named rather than
    silently overwritten. `reveal_answer_key` recomputes the payload from the
    live graph and compares it to `sha256` before it opens anything, so
    editing the finding or the patch after the freeze shuts the key rather
    than quietly re-sealing.
    """
    has proposal_id: str;
    has patch_id: str;
    has finding_id: str;
    has canonical_payload: str;
    has sha256: str = "";
    has frozen: bool = False;
    has note: str = "";
}

node StagingReceipt {
    """What one drafting attempt actually produced. Written once, never rewritten.

    The `drafted_*` fields are the typed draft **exactly as it arrived**, before
    deterministic validation had a chance to replace it. That is the whole
    point of this node existing: `stage_repair` used to hand back a draft
    rebuilt from the staged `PatchCandidate`, so "the draft agrees with what was
    staged" was a comparison of the patch with itself and could not fail. On a
    run where the model's draft was refused, the refused draft vanished
    entirely and the cached candidate was presented in its place.

    Now the two sides are independent. On the model path the recorded draft and
    the staged narrow candidate are byte-identical and `agrees_with_staged` says
    so honestly. On a refused-draft run they differ - the record keeps what the
    model asked for, the graph keeps what Jac allowed - and the disagreement is
    the evidence, not a defect.

    `draft_status` is MODEL only when the byLLM draft survived validation.
    `validation_ok` and `validation_errors` are the deterministic verdict on the
    recorded draft; `draft_note` is why the run fell back, when it did.

    **APPEND-ONLY.** A second `stage_repair()` returns this record verbatim
    rather than drafting again or rebuilding it from whatever is on the graph.
    """
    has receipt_id: str;
    has finding_id: str;
    has origin: str;
    has draft_status: str;
    has draft_note: str = "";
    has validation_ok: bool = False;
    has validation_errors: list[str] = [];
    has drafted_target_clause_id: str = "";
    has drafted_kind: str = "";
    has drafted_param_days: int = 0;
    has drafted_text: str = "";
    has drafted_rationale: str = "";
    has narrow_patch_id: str = "";
    has broad_patch_id: str = "";
}

node CaseBook {
    """Container for the seeded control pack and any generated applicants."""
    has book_id: str = "ead-cases";
}

node Ledger {
    """Container for the agent's persisted attempt history."""
    has ledger_id: str = "ead-ledger";
}

# --------------------------------------------------------------------------
# Edges - typed endpoints so every traversal infers its node type.
# --------------------------------------------------------------------------

edge Sourced: Policy --> Source {}
edge Contains: Policy --> Clause {}
edge Precedes: Clause --> Clause {}
edge Guards: Policy --> Invariant {}
edge Holds: CaseBook --> Applicant {}
edge Produced: Applicant --> Outcome {}
edge Logged: Ledger --> Attempt {}
edge Concerns: Attempt --> Outcome {}
edge Minimises: Finding --> Applicant {}
edge Patches: PatchCandidate --> Clause {}
edge Found: Ledger --> Finding {}
edge Stages: Ledger --> PatchCandidate {}
edge Records: Ledger --> StagingReceipt {}
edge Proposes: Finding --> PatchCandidate {}
edge Freezes: PatchCandidate --> FrozenProposal {}

# --------------------------------------------------------------------------
# Plain data carried between the evaluator and its callers.
# --------------------------------------------------------------------------

obj PatchOverlay {
    """A staged patch's effect, carried by the evaluator for one traversal.

    This is the mechanism that stops a proposal from touching the law. The
    walker still reads the authoritative `Clause` node for everything; the
    overlay may only substitute that rung's parameter, or waive a rung that
    sits earlier in the ladder than the rung the patch targets. Both are
    scoped to a single traversal and neither is ever written back, which is
    why `C5.param_days` is still 180 after a regression run.
    """
    has patch_id: str = "";
    has target_clause_id: str = "";
    has target_precedence: int = 0;
    has param_days: int = -1;
    has bypasses_predecessors: bool = False;
}

obj ProposalFacts {
    """What a frozen proposal actually does, in the shape the grader compares.

    Carried from `engine_core.jac` into `engine/answer_key.jac` so the answer key
    grades a structured description of the sealed proposal rather than a pile
    of positional arguments. Declared here, in the blind zone, on purpose:
    every field is a fact about Trapdoor's own candidate, so nothing about the
    later amendment leaks into a module the proposing agent's imports can
