];


node LayerAnchor {
    has key: str;
    has label: str;
    has order: int;
}


# Stable identity/provenance companion for an existing schema node.
# The domain node remains the materialized graph entity.
node FixtureRecord {
    has fixture_id: str;
    has record_type: str;
    has layer_key: str;
    has label: str;
    has node_jid: str = "";
    has source_url: str = "";
    has retrieved_at: str = "";
    has retrieval_info: str = "";
