# from: jachacks-sf::PMN123__trapdoor::ingest_ecfr.jac
import json;
import from copy { deepcopy }
import from hashlib { sha256 }
import from pathlib { Path }
import from urllib.request { Request, urlopen }
import from xml.etree.ElementTree { Element, fromstring, tostring }


glob SNAPSHOT_DATE: str = "2022-01-01";
glob CITATION: str = "8 CFR 274a.13";
glob TARGET_SECTION: str = "274a.13";
glob SOURCE_URL: str =
    "https://www.ecfr.gov/api/versioner/v1/full/2022-01-01/title-8.xml";
glob RAW_AUDIT_PATH: str = ".jac/audit/title-8-2022-01-01.xml";
glob FIXTURE_PATH: str = "fixtures/ecfr/ead_2022_01_01.json";
glob FORBIDDEN_TAGS: list[str] = ["XREF", "EFFDNOTE", "CITA"];
glob PROVENANCE_NOTE: str =
    "Snapshot: 2022-01-01 · amendment cross-references stripped at ingest.";


type FixtureValue = str | int | list[str] | dict[str, int];
type FixtureData = dict[str, FixtureValue];


obj SanitizedSection {
    has body: str;
    has sanitized_xml: str;
    has removal_counts: dict[str, int];
    has stripped_count: int;
}


def local_tag(tag: str) -> str {
    return tag.rsplit("}", 1)[-1].upper();
}


def find_target_section(xml_text: str) -> Element[str] {
    document: Element[str] = fromstring(xml_text);
    matches: list[Element[str]] = [
        element
        for element in document.iter()
        if local_tag(str(element.tag)) == "DIV8"
        and element.get("N") == TARGET_SECTION
        and element.get("TYPE") == "SECTION"
    ];
    if len(matches) != 1 {
        raise ValueError(
            f"Expected one {CITATION} section, found {len(matches)}"
        );
    }
    return deepcopy(matches[0]);
}


def count_forbidden_elements(section: Element[str]) -> dict[str, int] {
    counts: dict[str, int] = {tag: 0 for tag in FORBIDDEN_TAGS};
    for element in section.iter() {
        tag_name: str = local_tag(str(element.tag));
        if tag_name in counts {
            counts[tag_name] += 1;
        }
    }
    return counts;
}


def remove_forbidden_elements(parent: Element[str]) {
    children: list[Element[str]] = list(parent);
    for child in children {
        tag_name: str = local_tag(str(child.tag));
        if tag_name in FORBIDDEN_TAGS {
            current_children: list[Element[str]] = list(parent);
            child_index: int = current_children.index(child);
            tail_text: str = child.tail or "";
            if tail_text {
                if child_index > 0 {
                    previous: Element[str] =
                        current_children[child_index - 1];
                    previous.tail = (previous.tail or "") + tail_text;
                } else {
                    parent.text = (parent.text or "") + tail_text;
                }
            }
            parent.remove(child);
        } else {
            remove_forbidden_elements(child);
        }
    }
}


def normalized_element_text(element: Element[str]) -> str {
    return " ".join("".join(element.itertext()).split());
}


def render_section_body(section: Element[str]) -> str {
    lines: list[str] = [];
    for child in list(section) {
        line: str = normalized_element_text(child);
        if line {
            lines.append(line);
        }
    }
    return "\n".join(lines);
}


def sanitize_section_xml(xml_text: str) -> SanitizedSection {
    section: Element[str] = find_target_section(xml_text);
    counts: dict[str, int] = count_forbidden_elements(section);
    remove_forbidden_elements(section);
    body: str = render_section_body(section);
    sanitized_xml: str = tostring(section, encoding="unicode") as str;
    return SanitizedSection(
        body=body,
        sanitized_xml=sanitized_xml,
        removal_counts=counts,
        stripped_count=sum(counts.values()),
    );
}


def build_fixture(xml_text: str) -> FixtureData {
    sanitized: SanitizedSection = sanitize_section_xml(xml_text);
    fixture: FixtureData = {
        "citation": CITATION,
        "snapshot_date": SNAPSHOT_DATE,
        "source_url": SOURCE_URL,
        "body": sanitized.body,
        "ingest_mode": "INGESTED",
        "stripped_elements": FORBIDDEN_TAGS.copy(),
        "removal_counts": sanitized.removal_counts,
        "stripped_count": sanitized.stripped_count,
        "provenance_note": PROVENANCE_NOTE,
        "body_sha256": sha256(sanitized.body.encode("utf-8")).hexdigest(),
    };
    return fixture;
}


def fetch_official_title_8_snapshot -> str {
    audit_path: Path = Path(RAW_AUDIT_PATH);
    audit_path.parent.mkdir(parents=True, exist_ok=True);
    request: Request = Request(
        SOURCE_URL,
        headers={"User-Agent": "Trapdoor-JacHacks/1.0 source-ingest"},
    );
    response = urlopen(request, timeout=90);
    payload: bytes = response.read() as bytes;
    response.close();
    _ = audit_path.write_bytes(payload);
    return payload.decode("utf-8");
}


def write_fixture(fixture: FixtureData) {
    fixture_path: Path = Path(FIXTURE_PATH);
    fixture_path.parent.mkdir(parents=True, exist_ok=True);
    rendered: str = json.dumps(
        fixture,
        ensure_ascii=False,
        indent=2,
        sort_keys=True,
    ) as str;
    _ = fixture_path.write_text(rendered + "\n", encoding="utf-8");
}


def ingest_official_snapshot -> FixtureData {
    fixture: FixtureData = build_fixture(
        fetch_official_title_8_snapshot()
    );
    write_fixture(fixture);
    return fixture;
}


with entry:__main__ {
    artifact: FixtureData = ingest_official_snapshot();
    artifact_hash: str = artifact["body_sha256"] as str;
    print(f"Wrote {FIXTURE_PATH} ({artifact_hash})");
}

