"""Extract structured Event nodes and impact edges from news articles."""

import from models.types {
    ExtractedEdge, ExtractedNode, ExtractionResult, ScrapedDocument
}

glob EVENT_TYPES: list = [
    "Acquisition", "Funding", "ProductLaunch", "Regulation",
    "Partnership", "ModelRelease", "OpenSourceRelease"
];

glob MAX_EVENT_CHARS: int = 6000;

obj LLMExtractedEvent {
    has name: str,
        description: str = "",
        event_type: str = "",
        date: str = "",
        involved_entities: list[str] = [];
}

obj LLMEventEdge {
    has source: str,
        relationship: str,
        target: str,
        evidence: str,
        confidence: float = 0.0;
}

obj NewsEventExtraction {
    has events: list[LLMExtractedEvent],
        edges: list[LLMEventEdge];
}

sem NewsEventExtraction.events = "News events explicitly reported in the article. Never invent events.";
sem NewsEventExtraction.edges = "Impact relationships supported by quoted evidence linking events to companies or markets.";

sem LLMExtractedEvent.name = "Short headline-style event name from the article.";
sem LLMExtractedEvent.event_type = "One of: Acquisition, Funding, ProductLaunch, Regulation, Partnership, ModelRelease, OpenSourceRelease.";
sem LLMExtractedEvent.date = "ISO date YYYY-MM-DD if stated in article, otherwise empty string.";
sem LLMExtractedEvent.involved_entities = "Company or market names explicitly mentioned in relation to this event.";

def extract_events_from_text(content: str, source_url: str) -> NewsEventExtraction by llm(temperature=0.1, max_tokens=1200);
sem extract_events_from_text = "Extract news events and their ecosystem impact from a news article. Only include events explicitly reported. Every edge must quote or closely paraphrase the source. If no events found, return empty lists. Do not guess dates.";
sem extract_events_from_text.content = "News article markdown.";
sem extract_events_from_text.source_url = "URL of the news article.";

def normalize_event_type(value: str) -> str {
    cleaned = value.strip();
    for allowed in EVENT_TYPES {
        if cleaned.lower() == allowed.lower() {
            return allowed;
        }
    }
    if cleaned {
        return "ProductLaunch";
    }
    return "ProductLaunch";
}

def events_to_extraction(raw: NewsEventExtraction) -> ExtractionResult {
    nodes = [];
    edges = [];
    seen = set();

    for evt in raw.events {
        name = evt.name.strip();
        if not name {
            continue;
        }
        key = name.lower();
        if key in seen {
            continue;
        }
        seen.add(key);
        props = {
            "event_type": normalize_event_type(evt.event_type),
            "date": evt.date.strip()
        };
        nodes.append(
            ExtractedNode(
                type="Event",
                name=name,
                description=evt.description.strip(),
                properties=props
            )
        );
        for entity in evt.involved_entities {
            ent = entity.strip();
            if not ent {
                continue;
            }
            edges.append(
                ExtractedEdge(
                    source=name,
                    relationship="involves",
                    target=ent,
                    evidence=evt.description.strip() or f"Event reported involving {ent}.",
                    confidence=0.75
                )
            );
        }
    }

    for edge in raw.edges {
        rel = edge.relationship.strip();
        if rel not in ["impacts", "affects", "involves", "acquires", "launches"] {
            if rel == "acquired" {
                rel = "acquires";
            } else {
                rel = "impacts";
            }
        }
        evidence = edge.evidence.strip();
        source = edge.source.strip();
        target = edge.target.strip();
        if not evidence or not source or not target {
            continue;
        }
        conf = edge.confidence;
        if conf <= 0.0 {
            conf = 0.7;
        }
        if conf > 0.95 {
            conf = 0.95;
        }
        edges.append(
            ExtractedEdge(
                source=source,
                relationship=rel,
                target=target,
                evidence=evidence,
                confidence=conf
            )
        );
    }

    return ExtractionResult(nodes=nodes, edges=edges);
}

def safe_extract_events(doc: ScrapedDocument) -> ExtractionResult {
    if not doc.markdown.strip() {
        return ExtractionResult(nodes=[], edges=[]);
    }
    content = doc.markdown;
    if len(content) > MAX_EVENT_CHARS {
        content = content[:MAX_EVENT_CHARS];
    }
    try {
        raw = extract_events_from_text(content, doc.url);
        return events_to_extraction(raw);
    } except Exception {
        return ExtractionResult(nodes=[], edges=[]);
    }
}

