"""Direct HTTP to phone Ollama (OpenAI-compatible). Avoids byllm Model import at start."""

import os;
import json;
import re;
import urllib.request;
import from engine.model.objects {
    TriageInput, Triage, ActionScan, ActionDraft, ReplyContext, ReplyDraft,
    IdentityHint, MatchVerdict
}

glob RELAY_LOCAL_LLM_BASE: str = os.environ.get(
    "RELAY_LOCAL_LLM_BASE", "http://127.0.0.1:11434/v1"
);
glob RELAY_LOCAL_LLM_MODEL: str = os.environ.get(
    "RELAY_LOCAL_LLM_MODEL", "gemma2:2b"
);
# Council/ingest hot path — cap wait so Now gets a card in ~1–3s when Gemma is down.
glob RELAY_COUNCIL_LLM_TIMEOUT_MS: int = int(
    os.environ.get("RELAY_COUNCIL_LLM_TIMEOUT_MS", "2500") or "2500"
);

def _ollama_model_id -> str {
    m = RELAY_LOCAL_LLM_MODEL;
    if m.startswith("openai/") {
        return m[7:];
    }
    return m;
}

def local_chat(prompt: str, max_tokens: int = 192) -> str {
    base = RELAY_LOCAL_LLM_BASE.rstrip("/");
    payload = {
        "model": _ollama_model_id(),
        "messages": [{"role": "user", "content": prompt}],
        "max_tokens": max_tokens,
        "temperature": 0.2,
        "stream": False
    };
    raw = json.dumps(payload).encode("utf-8");
    req = urllib.request.Request(
        f"{base}/chat/completions",
        data=raw,
        headers={"Content-Type": "application/json"},
        method="POST"
    );
    timeout_s = float(RELAY_COUNCIL_LLM_TIMEOUT_MS) / 1000.0;
    if timeout_s < 0.5 {
        timeout_s = 0.5;
    }
    resp = urllib.request.urlopen(req, timeout=timeout_s);
    try {
        body = resp.read().decode("utf-8");
    } except Exception {
        resp.close();
        raise;
    }
    resp.close();
    data = json.loads(body);
    return str(data["choices"][0]["message"]["content"]);
}

def _extract_json_obj(text: str) -> dict[str, any] {
    t: str = str(text).strip();
    if t.startswith("```") {
        t = str(re.sub(r"^```(?:json)?\s*", "", t));
        t = str(re.sub(r"\s*```$", "", t));
    }
    try {
        return json.loads(t);
    } except Exception {
        m = re.search(r"\{[\s\S]*\}", t);
        if m {
            return json.loads(m.group(0));
        }
        raise;
    }
}

def triage_via_local(inp: TriageInput) -> Triage {
    prompt = (
        "Classify one phone notification for a blind user. "
        "Reply with ONLY compact JSON keys: "
        "urgency (NOISE|LOW|NORMAL|HIGH|CRITICAL), "
        "category (PERSONAL|WORK|FINANCE|HEALTH|LOGISTICS|PROMO|SCAM_SUSPECT|SYSTEM), "
        "needs_reply (bool), scam_risk (0..1), one_line_summary (short spoken English).\n"
        f"channel={inp.channel}\n"
        f"person={inp.person_name}\n"
        f"prior={inp.person_urgency_prior}\n"
        f"trust={inp.person_trust}\n"
        f"hour={inp.local_hour}\n"
        f"corroborated={inp.corroborated_by_second_device}\n"
        f"context={inp.recent_context}\n"
        f"preview={inp.preview}\n"
    );
    data = _extract_json_obj(local_chat(prompt, 160));
    urg = str(data.get("urgency", "NORMAL")).upper();
    if urg not in ["NOISE", "LOW", "NORMAL", "HIGH", "CRITICAL"] {
        urg = "NORMAL";
    }
    cat = str(data.get("category", "PERSONAL")).upper();
    return Triage(
        urgency=urg,
        category=cat,
        needs_reply=bool(data.get("needs_reply", False)),
        scam_risk=float(data.get("scam_risk", 0.0)),
        one_line_summary=str(data.get("one_line_summary", ""))[:160]
    );
}

def extract_actions_via_local(person_name: str, snippet: str, context: str) -> ActionScan {
    prompt = (
        "Find future commitments. Reply ONLY JSON: "
        '{"items":[{"text":"...","owner_is_user":true,"due_in_minutes":5,'
        '"confidence":0.7,"counterpart_name":""}]}\n'
        f"person={person_name}\nsnippet={snippet}\ncontext={context}\n"
    );
    data = _extract_json_obj(local_chat(prompt, 220));
    items: list[ActionDraft] = [];
    raw_items = data.get("items", []);
    if isinstance(raw_items, list) {
        for r in raw_items {
            if not isinstance(r, dict) {
                continue;
            }
            items.append(ActionDraft(
                text=str(r.get("text", ""))[:200],
                owner_is_user=bool(r.get("owner_is_user", False)),
                due_in_minutes=int(r.get("due_in_minutes", 0) or 0),
                confidence=float(r.get("confidence", 0.5) or 0.5),
                counterpart_name=str(r.get("counterpart_name", ""))[:80]
            ));
        }
    }
    return ActionScan(items=items);
}

def summarize_via_local(previous: str, recent_lines: list[str]) -> str {
    joined = " | ".join([x for x in recent_lines if len(x.strip()) > 0][:5]);
    prompt = (
        "Update a two-sentence contact profile. Reply with plain text only.\n"
        f"previous={previous}\nrecent={joined}\n"
    );
    out = local_chat(prompt, 120).strip();
    if len(out) > 220 {
        return out[:217] + "...";
    }
    return out;
}

def resolve_identity_via_local(left: IdentityHint, right: IdentityHint) -> MatchVerdict {
    prompt = (
        "Decide if two contact identities are the same person. Reply ONLY JSON: "
        '{"is_same_person":true,"confidence":0.8,"reason":"..."}\n'
        f"left_name={left.display_name} left_channel={left.channel} left_handle={left.handle_display}\n"
        f"right_name={right.display_name} right_channel={right.channel} right_handle={right.handle_display}\n"
    );
    data = _extract_json_obj(local_chat(prompt, 120));
    return MatchVerdict(
        is_same_person=bool(data.get("is_same_person", False)),
        confidence=float(data.get("confidence", 0.0) or 0.0),
        reason=str(data.get("reason", ""))[:160]
    );
}

def draft_via_local(ctx: ReplyContext) -> ReplyDraft {
    acts = "; ".join(ctx.open_actions[:3]);
    prompt = (
        "Write a short texting reply. Reply ONLY JSON keys: "
        "body, rationale, confidence (0..1), needs_human_detail (bool). "
        "Do not invent facts.\n"
        f"person={ctx.person_name}\nchannel={ctx.channel}\n"
        f"incoming={ctx.incoming}\nthread={ctx.thread_context}\nopen={acts}\n"
    );
    data = _extract_json_obj(local_chat(prompt, 160));
    return ReplyDraft(
        body=str(data.get("body", ""))[:400],
        rationale=str(data.get("rationale", ""))[:200],
        confidence=float(data.get("confidence", 0.5) or 0.5),
        needs_human_detail=bool(data.get("needs_human_detail", True))
    );
}

# Language: Jac
# from: jachacks-sf::bfay1__jaul::telephony__voice.jac
"""ElevenLabs text-to-speech - strictly opt-in, never on the critical path.

Synthesizes the agent's spoken line into audio for Twilio's <Play> verb, in
place of Twilio's built-in Polly voice. Owns the ElevenLabs REST call directly
(no `elevenlabs` SDK) so it stays a small, dependency-light, offline-testable
module - the same reasoning transport.jac gives for avoiding the `twilio` SDK
on its hot path.

Opt-in contract callers rely on: if ELEVENLABS_API_KEY is unset, or the call
fails or times out for any reason, `synthesize()` returns None rather than
raising. server.jac treats None as "fall back to the Polly <Say> voice for
this turn" - a live call must never crash or stall because ElevenLabs is
unreachable, slow, or out of quota.
"""
import os;
import uuid;
import requests;

glob _ELEVENLABS_TTS_URL: str = "https://api.elevenlabs.io/v1/text-to-speech/{voice_id}";
glob _DEFAULT_MODEL_ID: str = "eleven_flash_v2_5";

# Twilio hard-caps a webhook response at 15s total. Each /twiml/turn request
# already makes two sequential LLM calls (classify_response, generate_line)
# before it can even attempt this one - so a generous timeout here risks
# eating most of that 15s budget by itself if ElevenLabs is ever slow,
# tripping Twilio's own timeout (error 11200) and ending the call with
# "application error". A tight timeout means we fail fast and fall back to
# the Polly <Say> voice for that turn instead of running out the clock.
glob _TIMEOUT_SECONDS: int = 4;

# Two telephony-optimized formats were tried here and both proved wrong:
# - ulaw_8000: headerless raw PCM, the wrong shape for <Play> (a file fetch);
#   that format is meant for Twilio Media Streams (a WebSocket), not <Play>.
# - wav_8000: fetching a live clip and inspecting it with Python's `wave`
#   module showed ~40-46 SECONDS of audio for a single short sentence, at
#   every clip checked - a real defect in that specific format combination,
#   not just lower quality.
# mp3_44100_128 is ElevenLabs' own plain default and the format essentially
# every "ElevenLabs + Twilio <Play>" integration guide actually uses - Twilio
# transcodes it down to telephony quality itself, which is mature and
# well-tested, unlike our two attempts at doing that step ourselves.
glob _OUTPUT_FORMAT: str = "mp3_44100_128";
glob _CONTENT_TYPE: str = "audio/mpeg";

# clip_id -> (audio_bytes, content_type). In-memory only: fine for a
# single-process demo server (same assumption server.jac's `_sessions` dict
# already makes) since uvicorn's default single-worker event loop means no
# concurrent-write races. Would need a shared store (Redis, etc.) if this
# server ever ran with multiple workers/processes.
glob _clips: dict[str, tuple[bytes, str]] = {};
glob _MAX_CACHED_CLIPS: int = 50;


"""Whether ElevenLabs should be attempted at all."""
def enabled() -> bool {
    return bool(os.environ.get("ELEVENLABS_API_KEY"));
}


"""Synthesize `text`, cache the audio, and return its clip id.

Returns None (never raises) if ElevenLabs is not configured, or if the call
fails, times out, or comes back with a non-200 status.
"""
def synthesize(text: str) -> str | None {
    if not enabled() {
        return None;
    }

    voice_id = os.environ.get("ELEVENLABS_VOICE_ID");
    if not voice_id {
        return None;
    }

    api_key = os.environ["ELEVENLABS_API_KEY"];
    model_id = os.environ.get("ELEVENLABS_MODEL_ID") or _DEFAULT_MODEL_ID;

    try {
        resp = requests.post(
            _ELEVENLABS_TTS_URL.format(voice_id=voice_id),
            params={"output_format": _OUTPUT_FORMAT},
            headers={
                "xi-api-key": api_key,
                "Content-Type": "application/json"
            },
            json={"text": text, "model_id": model_id},
            timeout=_TIMEOUT_SECONDS
        );
    } except requests.RequestException {
        return None;
    }

    if resp.status_code != 200 {
        return None;
    }

    clip_id = uuid.uuid4().hex;
    _clips[clip_id] = (resp.content, _CONTENT_TYPE);
    _evict_if_over_capacity();
    return clip_id;
}


"""Look up previously synthesized audio by clip id, or None if unknown."""
def get_clip(clip_id: str) -> tuple[bytes, str] | None {
    return _clips.get(clip_id);
}


def _evict_if_over_capacity() {
    # Dicts preserve insertion order, so the oldest key is always the first
    # one - a plain FIFO cap is enough to bound memory across a long demo
    # session without coupling this module to call/session lifecycle.
    while len(_clips) > _MAX_CACHED_CLIPS {
        oldest = next(iter(_clips));
        del _clips[oldest];
    }
}

