"""byLLM triage + safe wrapper (ARCHITECTURE §8.1). Prefers phone Gemma when enabled."""

import from engine.model.objects { TriageInput, Triage, TriageResult }
import from engine.ai.fallback { fallback_triage }
import from engine.ai.router { cloud_llm_available, local_llm_available }
import from engine.ai.local_models { triage_via_local }
import from engine.ai.cloud_models { triage_via_cloud }

sem triage_notification = """
Classify one incoming notification for a blind user who is flooded with alerts.
Judge how much this deserves to interrupt them right now.
Treat marketing, app engagement nudges, and automated chatter as NOISE.
Treat medical, safety, fraud, security codes, and imminent logistics as CRITICAL or HIGH.
If a second household device saw the same contact in the same window, that is
independent evidence of urgency and should nudge urgency upward, not downward.
one_line_summary must be plain spoken English, naming the person and the point.
urgency must be one of: NOISE, LOW, NORMAL, HIGH, CRITICAL.
category must be one of: PERSONAL, WORK, FINANCE, HEALTH, LOGISTICS, PROMO, SCAM_SUSPECT, SYSTEM.
""";
sem TriageInput.preview = "Short notification preview text; may be empty if redacted for privacy.";
sem Triage.scam_risk = "0 to 1. Raise it for credential, payment, gift-card, or one-time-code pressure.";

def triage_notification(input: TriageInput) -> Triage by llm();

def triage_safe(inp: TriageInput, council_fast: bool = False) -> TriageResult {
    # Try every configured engine before deterministic fallback.
    if local_llm_available() {
        try {
            t = triage_via_local(inp);
            return TriageResult(triage=t, llm_available=True, engine="local");
        } except Exception {
            _ = True;
        }
    }
    if cloud_llm_available() and not council_fast {
        try {
            t = triage_via_cloud(inp);
            return TriageResult(triage=t, llm_available=True, engine="cloud");
        } except Exception {
            _ = True;
        }
    }
    return TriageResult(triage=fallback_triage(inp), llm_available=False, engine="fallback");
}

