"""HIPAAAuthGenerator walker — generates pre-filled HIPAA authorization forms."""

import from graph.nodes.patient { Patient }
import from graph.nodes.records_transfer { RecordsTransfer }
import from graph.nodes.legal_document { LegalDocument }
import from abilities.llm_abilities { generate_hipaa_auth_form }
import from datetime { datetime }
import from uuid { uuid4 }

walker HIPAAAuthGenerator {
    has forms_generated: int = 0;

    can generate with Patient entry {
        pending_transfers = [
            n for n in [here-->]
            if isinstance(n, RecordsTransfer)
            and n.status == "PENDING"
            and not n.hipaa_auth_generated
        ];

        for transfer in pending_transfers {
            form_content = generate_hipaa_auth_form(
                patient_name=here.name,
                patient_dob=here.dob,
                patient_address=here.address,
                purpose=transfer.purpose,
                sending_provider=transfer.sending_provider_name,
                receiving_provider=transfer.receiving_provider_name,
                authorization_date=datetime.utcnow().isoformat()[:10]
            );

            hipaa_doc = LegalDocument(
                legal_doc_id=str(uuid4()),
                doc_type="HIPAA_AUTHORIZATION",
                title=f"HIPAA Auth for {transfer.purpose}",
                plain_english_summary=form_content.get("form_text", ""),
                status="PENDING_SIGNATURE",
                effective_date=datetime.utcnow().isoformat()[:10],
                expiry_date=form_content.get("expiry_date", ""),
                created_at=datetime.utcnow().isoformat()
            );
            here ++> hipaa_doc;
            transfer.hipaa_auth_generated = True;
            self.forms_generated += 1;
        }

        report {"patient": here.name, "forms_generated": self.forms_generated};
    }
}

# language: jac
# from: jachacks-spring::kshitijkumrawat20__JacHacks2026::components__GreetCard.cl.jac
import from "@jac/runtime" { jacLogout, useNavigate, __doFuncFetch }

def:pub GreetCard() -> JsxElement {
    has greet_name: str = "";
    has greeting: str = "";
    has loading: bool = False;
    has error: str = "";

    navigate = useNavigate();

    def on_input(e: any) -> None {
        greet_name = e.target.value;
    }

    async def on_submit(e: any) -> None {
        e.preventDefault();
        loading = True;
        error = "";
        try {
            input_name = greet_name if greet_name else "World";
            result = await __doFuncFetch("greet", {"name": input_name});
            if result and result["message"] {
                greeting = str(result["message"]);
            }
        } except Exception as ex {
            msg = str(ex);
            if "UNAUTHORIZED" in msg {
                jacLogout();
                navigate("/login");
            } else {
                error = "Request failed: " + msg;
            }
        }
        loading = False;
    }

    return (
        <div className="card greet-card">
            <h2 className="greet-card-title">Try your backend</h2>
            <p className="greet-card-desc">
                Call the
                <code className="code-inline">greet</code>
                function in
                <code className="code-inline">services/appService.jac</code>
            </p>
            <form onSubmit={on_submit} className="greet-form">
                <input
                    className="input"
                    type="text"
                    value={greet_name}
                    onChange={on_input}
                    placeholder="Enter your name"
                    disabled={loading}
                />
                <button
                    className="btn btn-primary shrink-0"
                    type="submit"
                    disabled={loading}
                >
                    {("Calling..." if loading else "Greet")}
                </button>
            </form>
            {error and (
                <div className="error-box mt-3">{error}</div>
            )}
            {greeting and (
                <div className="result-box">{greeting}</div>
            )}
        </div>
    );
}

