"""Plan and run Firecrawl news discovery for recent ecosystem events."""

import from integrations.firecrawl { run_news_discovery }
import from models.types { ExpansionRunResult, ScrapedDocument }

def build_news_queries(
    company_name: str,
    market_hint: str = "",
    description: str = ""
) -> list {
    hint = market_hint.strip() if market_hint.strip() else "AI startups";
    name = company_name.strip() or "startup";
    queries = [
        f"{hint} acquisition news 2025 2026",
        f"{hint} funding round news",
        f"{hint} product launch announcement",
        f"{name} news",
        f"site:techcrunch.com {hint}",
        f"site:reuters.com {hint} AI"
    ];
    seen = set();
    result = [];
    for q in queries {
        key = q.lower();
        if key not in seen {
            seen.add(key);
            result.append(q);
        }
    }
    return result;
}

def spawn_event_discovery(
    company_name: str,
    market_hint: str = "",
    description: str = ""
) -> ExpansionRunResult {
    queries = build_news_queries(company_name, market_hint, description);
    return run_news_discovery(queries, []);
}

