            report ChatReplyView(thinking=thinking, reply="SF +1 day: downstream rescheduled, stale bookings marked NEEDS_REVIEW.",
                                 action="reschedule", city="San Francisco");
        } elif "complete" in msg {
            report ChatReplyView(thinking=thinking, reply="Trip complete! Plan node flipped to Memory (one field, zero migration).",
                                 action="complete", city="");
        } else {
            thinking.append("🧠 Generating suggestions...");
            report ChatReplyView(thinking=thinking,
                                 reply="Try: click a city card, or type i will go sf / sf +1 day / trip complete.",
                                 action="none", city="");
        }
    }
}

walker:pub complete_trip {
    has city: str = "";
    has reports: list[str] = [];

    can run with Root entry {
        for p in [-->[?:MemoryOrPlan]] {
            if p.kind == "PLAN" {
                p.kind = "MEMORY";   # one field flip, zero migration (P0.8)
                p.tags = p.tags + ["trip-complete"];
