"""Friend-safe redaction (ARCHITECTURE §7)."""

def friend_safe_view(payload: dict) -> dict {
    banned = ["preview", "title", "draft", "draft_body", "draft_rationale", "incoming", "body", "message", "text_content"];
    out: dict = {};
    for k in payload {
        if k in banned {
            continue;
        }
        val = payload[k];
        if isinstance(val, dict) {
            out[k] = friend_safe_view(val);
        } elif isinstance(val, list) {
            cleaned: list = [];
            for item in val {
                if isinstance(item, dict) {
                    cleaned.append(friend_safe_view(item));
                } else {
                    cleaned.append(item);
                }
            }
            out[k] = cleaned;
        } else {
            out[k] = val;
        }
    }
    return out;
}

