"""Model handles and routing (ARCHITECTURE §8.6). Local = phone Ollama/Gemma via adb reverse or LAN."""

import os;
import from engine.model.objects { LlmTarget }

# Gemma-first: local LLM on unless explicitly disabled (RELAY_LOCAL_LLM_ENABLED=false).
glob RELAY_LOCAL_LLM_ENABLED: bool = os.environ.get("RELAY_LOCAL_LLM_ENABLED", "true").lower() != "false";
glob RELAY_CLOUD_ENABLED: bool = os.environ.get("RELAY_CLOUD_ENABLED", "true").lower() != "false";
glob RELAY_LOCAL_LLM_BASE: str = os.environ.get(
    "RELAY_LOCAL_LLM_BASE", "http://127.0.0.1:11434/v1"
);

def _has_any_cloud_key() -> bool {
    keys = [
        "GEMINI_API_KEY",
        "GOOGLE_API_KEY",
        "OPENAI_API_KEY",
        "ANTHROPIC_API_KEY",
        "LLM_API_KEY"
    ];
    for k in keys {
        v = os.environ.get(k, "");
        if v and len(v) > 0 {
            return True;
        }
    }
    return False;
}

def cloud_llm_available() -> bool {
    return RELAY_CLOUD_ENABLED and _has_any_cloud_key();
}

def local_llm_available() -> bool {
    # When enabled, always attempt local HTTP (hub-side adb reverse or LAN).
    # Safe wrappers catch connection errors; do not gate on friend_ready here.
    return RELAY_LOCAL_LLM_ENABLED;
}

def any_llm_available() -> bool {
    return local_llm_available() or cloud_llm_available();
}

def pick_engine(tier: str, is_draft: bool, friend_ready: bool, friend_device_id: str) -> LlmTarget {
    t = (tier or "NORMAL").upper();
    # Prefer local Gemma whenever configured; cloud for drafts/urgent as co-primary.
    if is_draft or t in ["CRITICAL", "HIGH"] {
        if local_llm_available() {
            return LlmTarget(
                engine="local",
                device_id=friend_device_id if friend_ready else "",
                base_url=RELAY_LOCAL_LLM_BASE
            );
        }
        if cloud_llm_available() {
            return LlmTarget(engine="cloud", device_id="", base_url="");
        }
        return LlmTarget(engine="fallback", device_id="", base_url="");
    }
    if local_llm_available() {
        return LlmTarget(
            engine="local",
            device_id=friend_device_id if friend_ready else "",
            base_url=RELAY_LOCAL_LLM_BASE
        );
    }
    if cloud_llm_available() {
        return LlmTarget(engine="cloud", device_id="", base_url="");
    }
    return LlmTarget(engine="fallback", device_id="", base_url="");
}

