import from engine.ai.router { cloud_llm_available, local_llm_available }
import from engine.ai.local_models { draft_via_local }
import from engine.ai.cloud_models { draft_via_cloud }

sem draft_reply = """
Write a short reply the user can send as-is. Match a normal texting register:
warm, brief, no corporate filler, no emoji unless the incoming message used them.
Never invent facts, times, prices, or commitments that are not in the context.
If a fact is required but unknown, set needs_human_detail true and leave a clear
short gap the user can fill by voice, for example: "I can do <time>".
rationale is one sentence explaining the choice, for the user to hear before sending.
""";

def draft_reply(ctx: ReplyContext) -> ReplyDraft by llm();

def draft_reply_safe(ctx: ReplyContext, council_fast: bool = False) -> DraftResult {
    if local_llm_available() {
        try {
            return DraftResult(draft=draft_via_local(ctx), llm_available=True);
        } except Exception {
            _ = True;
        }
    }
    if cloud_llm_available() and not council_fast {
        try {
            return DraftResult(draft=draft_via_cloud(ctx), llm_available=True);
        } except Exception {
            _ = True;
        }
    }
    return DraftResult(draft=fallback_draft_reply(ctx), llm_available=False);
}

