"""Rolling person summary — phone Gemma when enabled, else cloud, else deterministic."""

import from engine.ai.router { cloud_llm_available, local_llm_available }
import from engine.ai.local_models { summarize_via_local }
import from engine.ai.cloud_models { summarize_via_cloud }

sem summarize_person = """
Update a two-sentence working profile of this contact for a communication assistant:
who they are to the user, what they usually talk about, and how quickly they
typically need a response. Preserve stable facts from the previous summary.
""";

def summarize_person(previous: str, recent_lines: list[str]) -> str by llm();

def summarize_person_safe(previous: str, recent_lines: list[str]) -> str {
    if local_llm_available() {
        try {
            return summarize_via_local(previous, recent_lines);
        } except Exception {
            _ = True;
        }
    }
    if cloud_llm_available() {
        try {
            return summarize_via_cloud(previous, recent_lines);
        } except Exception {
            _ = True;
        }
    }
    return _deterministic_summary(previous, recent_lines);
}

"""Fast profile append on ingest — Gemma refresh runs in RefreshPersonSummaries."""
def summarize_person_inline(previous: str, recent_lines: list[str]) -> str {
    return _deterministic_summary(previous, recent_lines);
}

def _deterministic_summary(previous: str, recent_lines: list[str]) -> str {
    lines: list[str] = [];
    for line in recent_lines {
        t = line.strip();
        if len(t) > 0 {
            lines.append(t);
        }
    }
    if len(lines) == 0 {
        return previous[:220] if len(previous) > 0 else "";
    }
    tail: list[str] = [];
    i = len(lines) - 1;
    while i >= 0 and len(tail) < 3 {
        cand = lines[i][:80];
        if cand not in tail {
            tail = [cand] + tail;
        }
        i -= 1;
    }
    joined = " · ".join(tail);
    if len(previous) > 0 {
        first = previous.split(" · ")[0][:60];
        if first not in joined {
            joined = f"{first} · {joined}";
        }
    }
    if len(joined) > 220 {
        return joined[:217] + "...";
    }
    return joined;
}

