                "fontSize": "0.68rem",
                "lineHeight": "1.45",
                "color": shade
            }}
        >
            <strong style={{"letterSpacing": "0.12em"}}>{confidence}</strong>
            {"  " + note if note != "" else ""}
        </div>
    </div>;
}

